def transform(grid):
    h, w = len(grid), len(grid[0])
    g = [[7]*w for _ in range(h)]

    # Preserve maroon cells not belonging to a movable three-by-three shape.
    movable = set()
    vertical = []
    for c in range(w-2):
        if all(grid[r][c] == 0 and grid[r][c+2] == 0 for r in range(h-3, h)) and all(grid[r][c+1] == 0 for r in range(h-3)):
            vertical.append(c)
            for r in range(h-3, h):
                for j in range(c, c+3):
                    movable.add((r, j))

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 9 and (r, c) not in movable:
                g[r][c] = 9

    # Move each bracket to the opposite edge.
    for c in vertical:
        for r in range(h-3, h):
            for j in range(c, c+3):
                if grid[r][j] != 7:
                    g[r-(h-3)][j] = grid[r][j]

    for r in range(h-2):
        if all(grid[r+i][2] == 0 for i in range(3)) and all(grid[r+1][c] == 0 for c in range(2, w)):
            for i in range(3):
                for j in range(3):
                    g[r+i][w-3+j] = grid[r+i][j]
        if all(grid[r+i][w-3] == 0 for i in range(3)) and all(grid[r+1][c] == 0 for c in range(w-2)):
            for i in range(3):
                for j in range(3):
                    g[r+i][j] = grid[r+i][w-3+j]
    return g
